using System.Collections.Generic;
using UnityEngine;

public class AirWalkEmitter : ParticleEffect
{
	public static Dictionary<Vector2, float> _airWalkTimestamps;

	private GameObject mainRoomObj;

	private string mainRoomObjLevelName;

	private float timeStampThreshold = 0.75f;

	public static Dictionary<Vector2, float> AirWalkTimestamps
	{
		get
		{
			if (_airWalkTimestamps == null)
			{
				_airWalkTimestamps = new Dictionary<Vector2, float>();
			}
			return _airWalkTimestamps;
		}
	}

	public void EmitSingle(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null)
	{
		Vector2 key = ((Vector2?)position) ?? default(Vector2);
		key += new Vector2(0.5f, -0.5f);
		Vector3? vector = position;
		position = ((!vector.HasValue) ? ((Vector3?)null) : new Vector3?(vector.GetValueOrDefault() + new Vector3(0.5f, -0.5f, 0f)));
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			if (mainRoomObj == null || Application.loadedLevelName != mainRoomObjLevelName)
			{
				Room[] array = Object.FindObjectsOfType<Room>();
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i].gameObject.activeSelf)
					{
						mainRoomObj = array[i].gameObject;
						break;
					}
				}
			}
			if (mainRoomObj != null)
			{
				key += (Vector2)mainRoomObj.transform.position;
				Vector3? vector2 = position;
				position = ((!vector2.HasValue) ? ((Vector3?)null) : new Vector3?(vector2.GetValueOrDefault() + mainRoomObj.transform.position));
			}
		}
		if (!AirWalkTimestamps.ContainsKey(key) || !(Time.time - AirWalkTimestamps[key] < timeStampThreshold))
		{
			AirWalkTimestamps[key] = Time.time;
			base.Emit(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset);
		}
	}
}
