using Chaos.AnimatorExtensions;
using UnityEngine;

public class AnimEffect : MonoBehaviour
{
	public Animator anim;

	public string defaultAnimName = string.Empty;

	private Vector3 initialLocalEulerAngles;

	public bool playing;

	public bool skipAnimCheck;

	public bool ignoreAnimCheck;

	private string queuedAnimName;

	private float queuedAnimTime;

	private float queuedAnimSpeed = 1f;

	public virtual void Awake()
	{
		anim = GetComponentInChildren<Animator>();
		initialLocalEulerAngles = transform.localEulerAngles;
	}

	private void Start()
	{
		if (!playing)
		{
			gameObject.SetActive(value: false);
		}
	}

	public virtual void Play(Vector3 position = default(Vector3), string animName = "", float normalizedTime = 0f, Vector2 randomStartingRange = default(Vector2), float animSpeed = 1f, float givenScale = 1f, Vector3? localEulerAngles = null)
	{
		gameObject.SetActive(value: true);
		playing = true;
		transform.position = position;
		transform.localScale = Vector3.one * givenScale;
		if (randomStartingRange != Vector2.zero)
		{
			normalizedTime = Random.Range(randomStartingRange.x, randomStartingRange.y);
		}
		transform.localEulerAngles = initialLocalEulerAngles;
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		if (animName == string.Empty)
		{
			animName = defaultAnimName;
		}
		queuedAnimName = animName;
		queuedAnimTime = normalizedTime;
		queuedAnimSpeed = animSpeed;
		skipAnimCheck = true;
	}

	public void PlayAnim(string animName, float normalizedTime = 0f)
	{
		gameObject.SetActive(value: true);
		playing = true;
		anim.Play(animName, -1, normalizedTime);
		queuedAnimName = animName;
		queuedAnimTime = normalizedTime;
		queuedAnimSpeed = 1f;
		skipAnimCheck = true;
	}

	private void LateUpdate()
	{
		if (playing && gameObject.activeSelf && queuedAnimName != null)
		{
			anim.speed = queuedAnimSpeed;
			anim.Play(queuedAnimName, -1, queuedAnimTime);
			queuedAnimName = null;
			queuedAnimTime = 0f;
			queuedAnimSpeed = 1f;
		}
		else if (!ignoreAnimCheck)
		{
			if (skipAnimCheck)
			{
				skipAnimCheck = false;
			}
			else if (playing && anim.AnimPlayed())
			{
				gameObject.SetActive(value: false);
				playing = false;
			}
		}
	}

	public float GetAnimTime()
	{
		return anim.GetAnimTime();
	}
}
