using System.Collections;
using UnityEngine;

public class DustEmitter : MonoBehaviour
{
	private static GameObject prefab;

	private Transform parentTrans;

	private ParticleSystem circPartSys;

	private ParticleSystem dirPartSys;

	private float dirOriSpeed;

	private float dirOriSize;

	private float dirOriLife;

	private float circOriSpeed;

	private float circOriSize;

	private float circOriLife;

	private ParticleSystem.ShapeModule circleShapeModule;

	private ChaosQuickStopwatch disableStopwatch = new ChaosQuickStopwatch();

	public static GameObject Prefab
	{
		get
		{
			if (prefab == null)
			{
				prefab = ChaosBundle.Get("Assets/Prefabs/Effects/DustEmitter.prefab");
			}
			return prefab;
		}
	}

	private void Awake()
	{
		dirPartSys = transform.Find("DustDirectionalBurstEmitter").GetComponent<ParticleSystem>();
		circPartSys = transform.Find("DustCircleEmitter").GetComponent<ParticleSystem>();
		circleShapeModule = circPartSys.shape;
		dirOriSpeed = dirPartSys.startSpeed;
		dirOriSize = dirPartSys.startSize;
		dirOriLife = dirPartSys.startLifetime;
		circOriSpeed = circPartSys.startSpeed;
		circOriSize = circPartSys.startSize;
		circOriLife = circPartSys.startLifetime;
	}

	private void LateUpdate()
	{
		if (parentTrans != null)
		{
			transform.position = parentTrans.position;
		}
	}

	public void Initialize(Transform givenTrans)
	{
		parentTrans = givenTrans;
	}

	public void EmitCircle(int particleCount = 40, float scale = 1f, float startSpeed = -1f, float startSize = -1f, Vector3? emitPosition = null, Vector3? emitterRotation = null)
	{
		gameObject.SetActive(value: true);
		if (emitPosition.HasValue)
		{
			transform.position = emitPosition.Value;
		}
		else if (parentTrans != null)
		{
			transform.position = parentTrans.position;
		}
		circleShapeModule.radius = scale;
		circPartSys.startSpeed = ((startSpeed != -1f) ? startSpeed : circOriSpeed);
		circPartSys.startSize = ((startSize != -1f) ? startSize : circOriSize);
		if (emitterRotation.HasValue)
		{
			circPartSys.transform.localEulerAngles = emitterRotation.Value;
		}
		circPartSys.Emit(particleCount);
		if (parentTrans == null && gameObject.activeSelf)
		{
			StartCoroutine(DelayedDisable(circOriLife));
		}
	}

	public void EmitDirBurst(int particleCount = 10, float targetAngle = 0f, float startSpeed = -1f, float startSize = -1f, float startLife = -1f, Vector3? emitPosition = null)
	{
		gameObject.SetActive(value: true);
		if (emitPosition.HasValue)
		{
			transform.position = emitPosition.Value;
		}
		else if (parentTrans != null)
		{
			transform.position = parentTrans.position;
		}
		dirPartSys.transform.localEulerAngles = new Vector3(270f + targetAngle, 270f, 0f);
		dirPartSys.startSpeed = ((startSpeed != -1f) ? startSpeed : dirOriSpeed);
		dirPartSys.startSize = ((startSize != -1f) ? startSize : dirOriSize);
		dirPartSys.startLifetime = ((startLife != -1f) ? startLife : dirOriLife);
		dirPartSys.Emit(particleCount);
		if (parentTrans == null && gameObject.activeSelf)
		{
			StartCoroutine(DelayedDisable(dirPartSys.startLifetime));
		}
	}

	public void StopEmissions()
	{
		circPartSys.Stop();
		dirPartSys.Stop();
		if (parentTrans == null)
		{
			gameObject.SetActive(value: false);
		}
	}

	private IEnumerator DelayedDisable(float givenValue)
	{
		if (disableStopwatch.IsRunning)
		{
			disableStopwatch.SetDelay(givenValue, stopCurrent: true, autoStart: true);
			yield break;
		}
		disableStopwatch.SetDelay(givenValue, stopCurrent: true, autoStart: true);
		while (disableStopwatch.IsRunning)
		{
			yield return null;
		}
		gameObject.SetActive(value: false);
	}
}
