	private float lineEmissionRatio = 1f;

	public ParticleSystem debrisEmitter;

	private ParticleSystem.EmissionModule debrisEmissionMod;

	private ParticleSystem.ShapeModule debrisShapeMod;

	public ParticleSystem lineEmitter;

	private ParticleSystem.EmissionModule lineEmissionMod;

	private ParticleSystem.ShapeModule lineShapeMod;

	public override void Awake()
	{
		base.Awake();
		originalEmitRate = emissionMod.rateOverTime.constantMax;
		debrisEmissionRatio = debrisEmitter.emissionRate / effectEmitter.emissionRate;
		debrisEmissionMod = debrisEmitter.emission;
		debrisShapeMod = debrisEmitter.shape;
		lineEmissionRatio = lineEmitter.emissionRate / effectEmitter.emissionRate;
		lineEmissionMod = lineEmitter.emission;
		lineShapeMod = lineEmitter.shape;
	}

	private void SetSubEmitterProperties(float? emissionRate = null, int? particleCount = null)
	{
		if (emissionRate.HasValue)
		{
			debrisEmissionMod.enabled = true;
			debrisEmitter.emissionRate = emissionRate.Value * debrisEmissionRatio;
			debrisEmitter.Play();
			lineEmissionMod.enabled = true;
			lineEmitter.emissionRate = emissionRate.Value * lineEmissionRatio;
			lineEmitter.Play();
		}
		if (particleCount.HasValue)
		{
			debrisEmitter.Emit(particleCount.Value);
			lineEmitter.Emit(particleCount.Value);
		}
	}

	public override void Stop()
	{
		base.Stop();
		debrisEmissionMod.enabled = false;
		debrisEmitter.Stop();
		lineEmissionMod.enabled = false;
		lineEmitter.Stop();
	}

	public override void Play(float? emissionRate = null, Vector3? position = null, ParticleSystemOverride overrides = null, float? playTime = null, Transform followTransform = null, Vector3? localEulerAngles = null, float delayTime = 0f, bool loop = true)
	{
		if (localEulerAngles.HasValue)
		{
			convertedLocalEulerAngles = localEulerAngles.Value;
			localEulerAngles = new Vector3(convertedLocalEulerAngles.x, convertedLocalEulerAngles.y, convertedLocalEulerAngles.z + 45f);
		}
		SetSubEmitterProperties(emissionRate);
		base.Play(emissionRate, position, overrides, playTime, followTransform, localEulerAngles, delayTime, loop);
	}

	public override void Emit(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, Transform followTransform = null)
	{
		if (localEulerAngles.HasValue)
		{
			convertedLocalEulerAngles = localEulerAngles.Value;
			localEulerAngles = new Vector3(convertedLocalEulerAngles.x, convertedLocalEulerAngles.y, convertedLocalEulerAngles.z + 45f);
		}
		SetSubEmitterProperties(null, particleCount);
		base.Emit(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset, followTransform);
	}
}

using UnityEngine;

public class EarthPillar : MonoBehaviour
{
	private static GameObject _prefab;

	[HideInInspector]
	public Animator anim;

	[HideInInspector]
	public Attack attackBox;

	private SpriteRenderer spriteRenderer;

	private SortSpriteLayer sortSpriteLayer;

	private bool pillarSpawned;

	private bool pillarDestroyed;

	[HideInInspector]
	public float spawnDelay = 0.5f;

	private int spawnStopwatchID;

	public float destroyDelay = 2f;

	private int destroyStopwatchID;

	public bool autoDestroy = true;

	public bool spawnExplosionOnDestroy;

	private bool explosionSpawned;

	private bool crackEffectSpawned;

	private bool crumbleSoundPlayed;

	private ParticleSystemOverride pSysOverride;

	public bool useWarnAnim = true;

	[HideInInspector]
	public bool playAudio = true;

	public static GameObject Prefab => _prefab ?? (_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthPillar.prefab"));

	private void Awake()
	{
		anim = GetComponent<Animator>();
		attackBox = transform.Find("AttackBox").GetComponent<Attack>();
		spriteRenderer = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		sortSpriteLayer = transform.Find("Sprite").GetComponent<SortSpriteLayer>();
		pSysOverride = new ParticleSystemOverride();
		pSysOverride.startSpeed = 9f;
	}

	private void Start()
	{
		pillarSpawned = false;
		pillarDestroyed = false;
		explosionSpawned = false;
		crackEffectSpawned = false;
		crumbleSoundPlayed = false;
		spawnStopwatchID = ChaosStopwatch.Begin(spawnDelay);
		sortSpriteLayer.enabled = false;
		transform.localScale = new Vector3((!((double)Random.value > 0.5)) ? 1f : (-1f), transform.localScale.y, transform.localScale.z);
	}

	private void Update()
	{
		if (!ChaosStopwatch.Check(spawnStopwatchID))
		{
			if (crackEffectSpawned || !(ChaosStopwatch.GetTimePercentage(spawnStopwatchID) >= 0.2f))
			{
				return;
			}
			crackEffectSpawned = true;
			if (useWarnAnim)
			{
				anim.Play("Warn", -1, 0f);
				if (spriteRenderer != null)
				{
					spriteRenderer.sortingLayerName = "TargetLineGround";
				}
			}
			else
			{
				anim.Play("Spawn", -1, 0f);
				sortSpriteLayer.sortOnlyOnce = autoDestroy;
				sortSpriteLayer.enabled = true;
				PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position, ParticleEffectOverrides.StartLifeTime0p75);
			}
		}
		else if (!pillarSpawned)
		{
			pillarSpawned = true;
			if (useWarnAnim)
			{
				if (spriteRenderer != null)
				{
					spriteRenderer.sortingLayerName = "Actor";
				}
				sortSpriteLayer.sortOnlyOnce = autoDestroy;
				sortSpriteLayer.enabled = true;
				anim.Play("Spawn", -1, 0f);
				PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position, ParticleEffectOverrides.StartLifeTime0p75);
			}
			destroyStopwatchID = ChaosStopwatch.Begin(destroyDelay);
		}
		else
		{
			if (pillarDestroyed)
			{
				return;
			}
			if (spawnExplosionOnDestroy && !explosionSpawned && ChaosStopwatch.GetRemainingTime(destroyStopwatchID) < 1f)
			{
				explosionSpawned = true;
				EarthExplosion component = Object.Instantiate(EarthExplosion.Prefab, transform.position, Quaternion.identity).GetComponent<EarthExplosion>();
				component.attackBox.SetAttackInfo(attackBox.atkInfo.skillCategory, "EarthExplosion");
				component.warmUpTime = 1f;
				component.transform.SetParent(transform);
			}
			if (!ChaosStopwatch.Check(destroyStopwatchID))
			{
				return;
			}
			pillarDestroyed = true;
			PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(1, transform.position + new Vector3(0f, 1f, 0f), pSysOverride);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(1, transform.position + new Vector3(0f, 0.5f, 0f), pSysOverride);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, transform.position + new Vector3(0f, 2f, 0f), pSysOverride);
			if (!crumbleSoundPlayed)
			{
				crumbleSoundPlayed = true;
				if (playAudio)
				{
					SoundManager.PlayAudioWithDistance("EarthCrumble", transform.position);
				}
			}
			anim.Play("Crumble", -1, 0f);
			if (autoDestroy && gameObject != null)
			{
				Object.Destroy(gameObject, 0.5f);
			}
			else
			{
				gameObject.SetActive(value: false);
			}
		}
	}

	public void EmitDust()
	{
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 10;
		float scale = 0.2f;
		Vector3? emitPosition = transform.position;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
	}

	public void Reset()
	{
		Start();
		gameObject.SetActive(value: true);
		anim.Play("Idle", -1, 0f);
	}
}

using System;
using UnityEngine;

public class EarthWheel : MonoBehaviour
{
	private static GameObject _prefab;

	public bool largeVersion;

	public SpriteRenderer spriteRenderer;

	public Animator anim;

	public Attack attack;

	public BoxCollider2D atkCollider;

	public BoxCollider2D preventFallCollider;

	public Movement movement;

	private string animStr;

	[HideInInspector]
	public Vector2 targetVector;

	private bool entityHit;

	private ChaosQuickStopwatch lifeTimer = new ChaosQuickStopwatch(2.25f);

	private ChaosQuickStopwatch speedUpTimer = new ChaosQuickStopwatch();

	private float speedUpLerpVal;

	private bool speedUpCompleted;

	private int hitCDStopwatchID = -1;

	public int maxHitCount = 14;

	private float hitDelay = 0.1f;

	private float minMoveSpeed = 2.25f;

	private float maxMoveSpeed = 40f;

	private NumVarStatMod moveSpeedMod;

	private ChaosQuickStopwatch spinTimer = new ChaosQuickStopwatch(0.2f);

	private float maxAnimSpeed = 1.25f;

	private float spinLerpValue;

	private bool spinCompleted;

	private static float trailIntervalFast = 0.025f;

	private static float trailIntervalSlow = 0.4f;

	private ChaosQuickStopwatch trailTimer = new ChaosQuickStopwatch(trailIntervalSlow);

	private Vector2 prevPos = Vector2.zero;

	private bool usingSlowTrailInterval = true;

	private Vector2 currentPosition;

	private Vector2 floorCrackOffset = Vector2.zero;

	private AudioSource wheelAudio;

	private bool destroyQueued;

	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthWheel.prefab");
			}
			return _prefab;
		}
	}

	private void Start()
	{
		PlayAnim();
		Activate();
	}

	private void PlayAnim()
	{
		animStr = ((!largeVersion) ? "Small" : string.Empty);
		float num = Vector2.Angle(Vector2.up, targetVector);
		bool flag = targetVector.x >= 0f;
		if (num <= 30f)
		{
			animStr += "SpawnUp";
			floorCrackOffset = Vector2.up;
		}
		else if (num <= 60f)
		{
			animStr += "SpawnUpRight";
			floorCrackOffset = Vector2.one;
		}
		else if (num <= 120f)
		{
			animStr += "SpawnRight";
			floorCrackOffset = Vector2.right;
		}
		else if (num <= 150f)
		{
			animStr += "SpawnUpRight";
			floorCrackOffset = new Vector2(1f, -1f);
			if (flag)
			{
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, -90f);
			}
			else
			{
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, 90f);
			}
		}
		else
		{
			animStr += "SpawnUp";
			floorCrackOffset = Vector2.up;
		}
		if (!flag)
		{
			spriteRenderer.transform.localScale = Globals.Vector3NegativeX;
			floorCrackOffset.x *= -1f;
		}
		anim.Play(animStr, -1, 0f);
		currentPosition = transform.position;
		floorCrackOffset = floorCrackOffset.normalized * ((!largeVersion) ? 0.5f : 0.9f);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition + floorCrackOffset);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition - floorCrackOffset);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition, RockDebrisEmitter.CircleExplosionOverride);
	}

	private void Activate()
	{
		lifeTimer.IsRunning = true;
		speedUpTimer.IsRunning = true;
		spinTimer.IsRunning = true;
		trailTimer.IsRunning = true;
		movement.moveSpeedStat.SetInitialBaseValue(0f);
		moveSpeedMod = new NumVarStatMod("EarthWheelSpeedMod", 0f, 10, VarStatModType.Override);
		movement.moveSpeedStat.AddMod(moveSpeedMod);
		movement.moveVector = targetVector;
		if (!largeVersion)
		{
			atkCollider.transform.localScale *= 0.75f;
			preventFallCollider.transform.localScale *= 0.75f;
		}
		preventFallCollider.transform.localEulerAngles = Globals.GetRotationVector(targetVector);
		atkCollider.transform.localEulerAngles = Globals.GetRotationVector(targetVector);
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(EntityHit));
		atkCollider.enabled = true;
		SoundManager.PlayAudioWithDistance("EarthCrumble", transform.position, null, 24f, -1f, 1.1f);
	}

	private void Update()
	{
		if (!destroyQueued)
		{
			HandleEffects(transform.position);
		}
	}

	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (!spinCompleted)
		{
			spinLerpValue = spinTimer.TimePercentage;
			anim.speed = Mathf.Lerp(0f, maxAnimSpeed, spinLerpValue);
			spinCompleted = spinLerpValue >= 1f;
			return;
		}
		movement.MoveToMoveVector();
		if (!entityHit)
		{
			if (!speedUpCompleted)
			{
				speedUpLerpVal = speedUpTimer.TimePercentage;
				moveSpeedMod.modValue = Mathf.Lerp(minMoveSpeed, maxMoveSpeed, Globals.GetSmoothLerpValue(speedUpLerpVal));
				movement.moveSpeedStat.AddMod(moveSpeedMod);
				speedUpCompleted = speedUpLerpVal >= 1f;
				if (usingSlowTrailInterval && speedUpLerpVal > 0.13f && trailTimer.Delay == trailIntervalSlow)
				{
					usingSlowTrailInterval = false;
					trailTimer.SetDelay(trailIntervalFast);
				}
			}
			if (!lifeTimer.IsRunning)
			{
				Disable();
			}
		}
		else
		{
			switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
			{
			case StopwatchState.Running:
				attack.collider.enabled = true;
				break;
			case StopwatchState.Ready:
				attack.collider.enabled = false;
				break;
			case StopwatchState.Done:
				Disable();
				break;
			}
		}
	}

	private void Disable()
	{
		destroyQueued = true;
		attack.collider.enabled = false;
		currentPosition = transform.position;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 30;
		float scale = 0.2f;
		float startSpeed = 5f;
		Vector3? emitPosition = currentPosition;
		poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition - targetVector * 0.5f, RockDebrisEmitter.SmallCircleExplosionOverride);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition + targetVector * 0.5f, RockDebrisEmitter.SmallCircleExplosionOverride);
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, currentPosition, RockDebrisEmitter.SmallCircleExplosionOverride);
		if (wheelAudio != null && wheelAudio.isPlaying)
		{
			wheelAudio.Stop();
		}
		string audioID = "RockFormShort";
		Vector2? soundOrigin = transform.position;
		startSpeed = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, startSpeed);
		UnityEngine.Object.Destroy(gameObject);
	}

	private void EntityHit(Entity entity)
	{
		if (!entityHit && !(entity == null) && !(entity is Destructible))
		{
			entityHit = true;
			trailTimer.SetDelay(trailIntervalSlow);
			usingSlowTrailInterval = true;
			spinTimer.IsRunning = false;
			movement.EndMovement();
			moveSpeedMod.modValue = minMoveSpeed;
			movement.moveSpeedStat.AddMod(moveSpeedMod);
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(EntityHit));
			atkCollider.size = new Vector2(atkCollider.size.x, 3f);
			hitCDStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
		}
	}

	private void HandleEffects(Vector2 givenPosition)
	{
		if (!trailTimer.IsRunning)
		{
			if (!usingSlowTrailInterval && speedUpCompleted && !entityHit)
			{
				if (prevPos == Vector2.zero)
				{
					prevPos = transform.position;
				}
				else if (Vector2.Distance(prevPos, transform.position) < 1f)
				{
					usingSlowTrailInterval = true;
					trailTimer.SetDelay(trailIntervalSlow);
				}
			}
			trailTimer.IsRunning = true;
			PoolManager.GetPoolItem<SectionedTrailEmitter>("FloorRift").Emit(givenPosition + targetVector, givenPosition - targetVector);
		}
		wheelAudio = SoundManager.PlayIfNotPlaying("Drill", wheelAudio, transform, useStdPitchOverride: false, -1f, 0.1f);
	}
}

