public class ElementalStatusEffect : MonoBehaviour
{
	private static GameObject prefab;

	private static Dictionary<ElementType, Color> elementColorDictionary = new Dictionary<ElementType, Color>
	{
		{
			ElementType.Neutral,
			Color.black
		},
		{
			ElementType.Chaos,
			Color.black
		},
		{
			ElementType.Fire,
			new Color(1f, 0.5f, 0f)
		},
		{
			ElementType.Air,
			Color.white
		},
		{
			ElementType.Earth,
			new Color(0.45f, 0.75f, 0.5f)
		},
		{
			ElementType.Lightning,
			Color.yellow
		},
		{
			ElementType.Water,
			new Color(0.4f, 0.6f, 1f)
		}
	};

	public ElementType element = ElementType.Neutral;

	public Transform followTrans;

	private ParticleSystem particleSys;

	[HideInInspector]
	public int burstCount = 200;

	[HideInInspector]
	public float duration = 0.5f;

	private int durationStopwatchID;

	private float destroyDelay = 1f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/ElementalStatusEffect.prefab"));

	private void Awake()
	{
		particleSys = GetComponent<ParticleSystem>();
	}

	private void Start()
	{
		particleSys.startColor = elementColorDictionary[element];
		particleSys.Emit(burstCount);
		particleSys.Play();
		durationStopwatchID = ChaosStopwatch.Begin(duration);
		Object.Destroy(gameObject, duration + destroyDelay);
	}

	private void Update()
	{
		if (ChaosStopwatch.Check(durationStopwatchID))
		{
			particleSys.Stop();
		}
	}

	private void LateUpdate()
	{
		if (followTrans != null && transform != null)
		{
			transform.position = followTrans.position;
		}
	}
}
