using System;
using System.Collections;
using Chaos.ArrayExtensions;
using Chaos.ParticleSystemExtensions;
using UnityEngine;
using UnityEngine.SceneManagement;

public class ParticleEffect : MonoBehaviour
{
	[HideInInspector]
	public ParticleSystem effectEmitter;

	[HideInInspector]
	public ParticleSystem.EmissionModule emissionMod;

	[HideInInspector]
	public ParticleSystem.ShapeModule shapeMod;

	public ParticleSystem[] subEmitters;

	[HideInInspector]
	private ParticleSystemOverride tempOverride;

	public int defaultParticleCount = 30;

	private int calcParticleCount;

	[HideInInspector]
	protected SortParticleLayer particleSorter;

	[HideInInspector]
	private float initialSortYOffset;

	public string[] soundOnEmit;

	public int soundEmitCount;

	public bool playing;

	public bool hasSubmitters;

	public ParticleSystemSnapshot initialSettings;

	public Transform followTransform;

	public Vector3 followOffset;

	public bool reqFollowTrans;

	public int playTimerID = -1;

	public AuxParticleEffect[] auxParticleEffects;

	protected bool delayRunning;

	public virtual void Awake()
	{
		effectEmitter = GetComponentInChildren<ParticleSystem>();
		emissionMod = effectEmitter.emission;
		shapeMod = effectEmitter.shape;
		tempOverride = new ParticleSystemOverride();
		initialSettings = effectEmitter.GetSnapshot();
		SetRandomSeed();
		if (hasSubmitters)
		{
			subEmitters = effectEmitter.transform.GetComponentsInChildren<ParticleSystem>();
		}
		particleSorter = GetComponentInChildren<SortParticleLayer>();
		if (particleSorter != null)
		{
			initialSortYOffset = particleSorter.yValueOffset;
		}
		SceneManager.sceneLoaded += OnSceneLoaded;
	}

	public virtual void ResetParticleSorter(float? newYOffset = null)
	{
		if (!(particleSorter == null))
		{
			particleSorter.yValueOffset = initialSortYOffset;
			if (newYOffset.HasValue)
			{
				particleSorter.yValueOffset = newYOffset.Value;
			}
		}
	}

	public virtual void SetRandomSeed()
	{
		effectEmitter.Stop();
		effectEmitter.randomSeed = (uint)UnityEngine.Random.Range(0, 9999999);
		effectEmitter.Play();
		effectEmitter.Stop();
	}

	public virtual void Emit(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, Transform followTransform = null)
	{
		if (gameObject != null)
		{
			gameObject.SetActive(value: true);
		}
		if (delayTime > 0f)
		{
			delayRunning = true;
			StartCoroutine(EmitDelayed(delayTime, particleCount, position, overrides, localEulerAngles));
			return;
		}
		calcParticleCount = (particleCount.HasValue ? particleCount.Value : defaultParticleCount);
		if (calcParticleCount == 0)
		{
			return;
		}
		effectEmitter.LoadSnapshot(initialSettings);
		ResetParticleSorter(sortYOffset);
		if (position.HasValue)
		{
			effectEmitter.transform.position = position.Value;
		}
		this.followTransform = null;
		if (followTransform != null)
		{
			this.followTransform = followTransform;
			effectEmitter.transform.position = this.followTransform.position;
		}
		effectEmitter.ApplyOverrides(overrides);
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		effectEmitter.Emit(calcParticleCount);
		if (soundOnEmit != null && soundOnEmit.Length >= 1 && soundEmitCount > 0)
		{
			for (int i = 0; i < soundEmitCount; i++)
			{
				SoundManager.PlayAudioWithDistance(soundOnEmit.GetRandomValue(), transform.position);
			}
		}
		if (auxParticleEffects != null && auxParticleEffects.Length > 0)
		{
			for (int j = 0; j < auxParticleEffects.Length; j++)
			{
				AuxParticleEffect auxParticleEffect = auxParticleEffects[j];
				PoolManager.GetPoolItem<ParticleEffect>(auxParticleEffect.effectName).Emit(auxParticleEffect.particleCount, (!position.HasValue) ? ((Vector3?)null) : new Vector3?(position.GetValueOrDefault() + auxParticleEffect.positionOffset), auxParticleEffect.overrides, auxParticleEffect.localEulerAngles, auxParticleEffect.delayTime, auxParticleEffect.sortYOffset, auxParticleEffect.followTransform);
			}
		}
	}

	private IEnumerator EmitDelayed(float delayTime, int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float? sortYOffset = null, Transform followTransform = null)
	{
		yield return new WaitForSeconds(delayTime);
		delayRunning = false;
		Emit(particleCount, position, overrides, localEulerAngles, 0f, sortYOffset, followTransform);
	}

	public virtual void Play(float? emissionRate = null, Vector3? position = null, ParticleSystemOverride overrides = null, float? playTime = null, Transform followTransform = null, Vector3? localEulerAngles = null, float delayTime = 0f, bool loop = true)
	{
		gameObject.SetActive(value: true);
		if (delayTime > 0f)
		{
			delayRunning = true;
			StartCoroutine(PlayDelayed(delayTime, emissionRate, position, overrides, playTime, followTransform, localEulerAngles));
			return;
		}
		effectEmitter.LoadSnapshot(initialSettings);
		ResetParticleSorter();
		if (emissionRate.HasValue)
		{
			effectEmitter.emissionRate = emissionRate.Value;
		}
		effectEmitter.loop = loop;
		if (position.HasValue)
		{
			effectEmitter.transform.position = position.Value;
		}
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		if (followTransform != null)
		{
			this.followTransform = followTransform;
		}
		if (this.followTransform != null)
		{
			effectEmitter.transform.position = this.followTransform.position;
		}
		effectEmitter.ApplyOverrides(overrides);
		emissionMod.enabled = true;
		effectEmitter.Play();
		if (playTime.HasValue)
		{
			playTimerID = ChaosStopwatch.Begin(playTime.Value);
		}
		playing = true;
	}

	private IEnumerator PlayDelayed(float delayTime, float? emissionRate = null, Vector3? position = null, ParticleSystemOverride overrides = null, float? playTime = null, Transform followTransform = null, Vector3? localEulerAngles = null)
	{
		yield return new WaitForSeconds(delayTime);
		delayRunning = false;
		Play(emissionRate, position, overrides, playTime, followTransform, localEulerAngles);
	}

	public virtual void Stop()
	{
		playing = false;
		followTransform = null;
		reqFollowTrans = false;
		playTimerID = -1;
		emissionMod.enabled = false;
		effectEmitter.Stop();
		if (hasSubmitters && subEmitters != null)
		{
			for (int i = 0; i < subEmitters.Length; i++)
			{
				subEmitters[i].Stop();
			}
		}
	}

	public void ClearAll()
	{
		effectEmitter.Clear();
		if (hasSubmitters && subEmitters != null)
		{
			for (int i = 0; i < subEmitters.Length; i++)
			{
				subEmitters[i].Clear();
			}
		}
	}

	public void Update()
	{
		if (playing && playTimerID != -1 && ChaosStopwatch.Check(playTimerID))
		{
			Stop();
		}
		if (delayRunning || effectEmitter == null || effectEmitter.isPlaying)
		{
			return;
		}
		if (hasSubmitters && subEmitters != null)
		{
			for (int i = 0; i < subEmitters.Length; i++)
			{
				if (subEmitters[i].isPlaying)
				{
					return;
				}
			}
		}
		gameObject.SetActive(value: false);
	}

	public void LateUpdate()
	{
		if (followTransform != null)
		{
			effectEmitter.transform.position = followTransform.position + followOffset;
		}
		else if (playing && reqFollowTrans)
		{
			Stop();
		}
	}

	public void SetSortLayer(string layerName)
	{
		effectEmitter.GetComponent<Renderer>().sortingLayerName = layerName;
	}

	public void SetStartRotation(float rotation)
	{
		tempOverride.startRotation = 0f - (float)Math.PI / 180f * rotation;
		effectEmitter.ApplyOverrides(tempOverride);
	}

	public void SetStartRotationAngles(Vector3 rotationAngles)
	{
		ParticleSystemOverride particleSystemOverride = tempOverride;
		Vector3 vector = rotationAngles;
		particleSystemOverride.startRotation = 0f - (float)Math.PI / 180f * vector.z;
		effectEmitter.ApplyOverrides(tempOverride);
	}

	public void OnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		Stop();
		effectEmitter.Stop();
		effectEmitter.Clear();
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}
}

