using Chaos.AnimatorExtensions;
using UnityEngine;

public class ThunderMage : Mage
{
	public class ThunderMageIonSpreadState(string newName, FSM newFSM, Enemy newEnt) : SkillState(newName, newFSM, newEnt, 0, 0, 0f, 0f, 0f, newAuto: false)
	{
		private Vector2 spawnPosition;

		private Vector2 targetOffset;

		private IonSpike[] ionArray = new IonSpike[3];

		private IonSpike currentIS;

		private bool ionReleased;

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("CastAlt");
			windupTime = StdWindupTime * 1.75f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			spawnPosition = parent.hurtBoxTransform.position;
			targetOffset = Globals.GetPerpendicular(targetVector) * 0.5f;
			ionArray[0] = CreateIonSpike(spawnPosition, targetVector);
			ionArray[1] = CreateIonSpike(spawnPosition + targetOffset, targetVector);
			ionArray[2] = CreateIonSpike(spawnPosition - targetOffset, targetVector);
			ionReleased = false;
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			DeactivatePowerUpEffect();
			parent.anim.Play("Cast");
			ionReleased = true;
		}

		public override void OnExit()
		{
			base.OnExit();
			if (ionReleased)
			{
				return;
			}
			for (int num = ionArray.Length - 1; num >= 0; num--)
			{
				if (ionArray[num] != null)
				{
					ionArray[num].AbortSpike();
				}
			}
		}

		private IonSpike CreateIonSpike(Vector2 givenPosition, Vector2 givenVector)
		{
			currentIS = ChaosInst<IonSpike>(IonSpike.Prefab, givenPosition + givenVector * 0.75f);
			currentIS.SetSkillInfo(parent.skillCategory, skillID);
			currentIS.attackVector = givenVector;
			currentIS.delayStopwatchID = ChaosStopwatch.Begin(windupTime);
			currentIS.maxRange = parent.attackRadius + 1f;
			currentIS.intervalCount = 5;
			return currentIS;
		}
	}

	public class ThunderMageThunderWaveState : SkillState
	{
		private ThunderWave currentTW;

		public ThunderMageThunderWaveState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			castingAnimName = "Drop";
			useTargetHurtBox = false;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.PlayDirectional(castingAnimName);
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.25f);
		}

		public override void WindupUpdate()
		{
			parent.anim.PlayDirectional(castingAnimName);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.anim.PlayDirectional(castingAnimName, -1, 0.5f);
			CreateThunderWave(parent.transform.position, targetVector);
		}

		private void CreateThunderWave(Vector2 givenPosition, Vector2 givenVector)
		{
			currentTW = ChaosInst<ThunderWave>(ThunderWave.Prefab, givenPosition + givenVector * 0.75f);
			currentTW.moveVector = givenVector;
			currentTW.SetSkillData(parent.skillCategory, skillID);
			currentTW.maxWaveCount = 7;
			currentTW.wavePoolSize = 7;
			currentTW.burstScale = 1.25f;
			currentTW.spacing = 1.5f;
			currentTW.spawnRate = 0.125f;
		}
	}

	public class ThunderMageThunderBlastState : SkillState
	{
		private ThunderBlast currentTB;

		private float burstRadius = 2f;

		private Vector2 targetPosition;

		private int atkStopwatchID;

		private int atkCount = 3;

		public ThunderMageThunderBlastState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			castingAnimName = "Drop";
			useTargetHurtBox = false;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.PlayDirectional(castingAnimName);
			windupTime = StdWindupTime * 1.25f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			atkStopwatchID = ChaosStopwatch.Begin(windupTime, useInterval: true, windupTime, atkCount);
		}

		public override void ExecuteSkill()
		{
			switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
			{
			case StopwatchState.Ready:
				parent.anim.PlayDirectional(castingAnimName, -1, 0.5f);
				targetPosition = ((parent.UpdateTargetInfo() != null) ? parent.closestTargetInfo.position : parent.transform.position);
				CreateThunderBlast(targetPosition + Random.insideUnitCircle, 0.5f);
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				DeactivatePowerUpEffect();
				break;
			}
		}

		private void CreateThunderBlast(Vector2 givenPosition, float givenDelay)
		{
			string animName = "Draw";
			Vector3 spawnPos = givenPosition;
			bool disableWithParentVal = true;
			GameObject gameObject = parent.gameObject;
			bool trackParentVal = false;
			bool useCastTimeVal = true;
			float unitSizeX = burstRadius;
			Color? color = CastingCircle.enemyColorDim;
			CastingCirclePool.Spawn(animName, spawnPos, disableWithParentVal, gameObject, trackParentVal, useCastTimeVal, givenDelay, unitSizeX, 0f, color);
			currentTB = Globals.ChaosInst<ThunderBlast>(ThunderBlast.Prefab, null, givenPosition);
			currentTB.SetSkillData(parent.skillCategory, skillID, 1);
			currentTB.atkRadius = burstRadius;
			currentTB.delayTime = givenDelay;
		}
	}

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new GoBackState("GoBack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(new RepositionState("Reposition", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyHurtState("Hurt", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
