				OnMoveStart(startPos, endPos);
			}
			if (moveCompleted && ChaosStopwatch.Check(exitStopwatchID))
			{
				ExitTransition();
			}
		}

		public override void FixedUpdate()
		{
			if (delayCompleted && !moveCompleted)
			{
				moveLerpVal = ChaosStopwatch.GetTimePercentage(moveStopwatchID);
				parent.transform.position = Vector3.Lerp(startPos, endPos, moveLerpVal);
				if (!(moveLerpVal < 1f))
				{
