					EndStealth();
					ToggleStealthEffects();
					parent.anim.PlayDirectional(endAnimName, -1, 1f);
					OnMoveEnd(startPos, endPos);
					exitStopwatchID = ChaosStopwatch.Begin(StdExitTime);
				}
			}
		}

