		{
			currentATK.transform.position = givenPosition;
			currentATK.SetAttackInfo(parent.skillCategory, skillID, givenIndex);
			currentATK.knockbackOverwriteVector = givenVector;
			currentATK.gameObject.SetActive(value: false);
			currentATK.gameObject.SetActive(value: true);
			PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningLine").Emit(parent.hurtBoxTransform.position, givenPosition - givenVector + Vector2.up);
			SoundManager.PlayWithDistAndSPR("TeleStrike", givenPosition);
