			parent.FaceTarget(givenPosition + givenVector);
			parent.anim.PlayDirectional("Stab" + parent.facingDirection, -1, 1f);
		}
	}

	private void DestroyAttack(float givenDelay = -1f)
	{
		if (!(currentATK != null))
		{
			return;
		}
		Attack attack = currentATK;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (currentATK.gameObject != null)
		{
			if (givenDelay > 0f)
			{
				UnityEngine.Object.Destroy(currentATK.gameObject, givenDelay);
			}
			else
