		{
		}

		public override void OnEnter()
		{
			parent.anim.Play("Idle", -1, UnityEngine.Random.Range(0f, 0.5f));
		}

		public override void Update()
		{
			parent.TrackClosestTarget();
			parent.LookAtTarget((parent.closestTargetInfo != null) ? parent.closestTargetInfo.hurtBoxPosition : Vector3.zero);
			if (parent.closestTargetInfo != null && ChaosStopwatch.Check(parent.barrageDelayStopwatchID))
			{
				parent.fsm.ChangeState("Attack");
			}
		}
	}

	public class AttackState : State<Turret>
	{
		private Vector2 shootVector;

		private TargetInfo lastValidTargetInfo;

		private bool useLastValidTargetInfo;

		private bool barrageTimerStarted;

		public AttackState(string stateName, FSM parentFSM, Turret parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			parent.attackWarningStopwatchID = ChaosStopwatch.Begin(parent.curTurretProp.attackWarningTime);
			parent.anim.Play("Alert");
			if (parent.isEnemy)
			{
				parent.eyeLight.color = parent.redLightColor;
			}
			lastValidTargetInfo = null;
			useLastValidTargetInfo = false;
			barrageTimerStarted = false;
		}

		public override void Update()
		{
			parent.TrackClosestTarget();
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.transform == null)
			{
				if (lastValidTargetInfo == null || lastValidTargetInfo.hurtBoxTransform == null)
				{
					parent.fsm.ChangeState("Idle");
					return;
				}
				useLastValidTargetInfo = true;
			}
			else
			{
				useLastValidTargetInfo = false;
				lastValidTargetInfo = parent.closestTargetInfo;
			}
			if (useLastValidTargetInfo)
			{
				parent.LookAtTarget(lastValidTargetInfo.hurtBoxPosition);
				shootVector = (lastValidTargetInfo.hurtBoxPosition - parent.turretIris.position).normalized;
			}
			else
			{
				parent.LookAtTarget(parent.closestTargetInfo.hurtBoxPosition);
				shootVector = (parent.closestTargetInfo.hurtBoxPosition - parent.turretIris.position).normalized;
			}
			if (!ChaosStopwatch.Check(parent.attackWarningStopwatchID))
			{
				return;
			}
			if (!barrageTimerStarted)
			{
				barrageTimerStarted = true;
				parent.shotDelayStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, parent.curTurretProp.shotDelayTime, parent.curTurretProp.shotsPerBarrage);
			}
			switch (ChaosStopwatch.CheckInterval(parent.shotDelayStopwatchID))
			{
			case StopwatchState.Ready:
			{
				shootVector += new Vector2(UnityEngine.Random.Range(0f - parent.curTurretProp.barrageAccuracy, parent.curTurretProp.barrageAccuracy), UnityEngine.Random.Range(0f - parent.curTurretProp.barrageAccuracy, parent.curTurretProp.barrageAccuracy));
				Projectile component = UnityEngine.Object.Instantiate(parent.laserBoltPrefab, parent.turretIris.position, Quaternion.identity).GetComponent<Projectile>();
				component.parentObject = parent.gameObject;
				component.moveVector = shootVector;
				component.attackBox.SetAttackInfo(parent.skillCategory, parent.skillID);
				parent.anim.Play("Attack");
				SoundManager.PlayAudioWithDistance("LaserBolt", parent.transform.position);
				break;
			}
			case StopwatchState.Running:
				break;
			case StopwatchState.Done:
				if (parent.anim.AnimPlayed())
				{
					parent.fsm.ChangeState("Idle");
				}
				break;
			}
		}

		public override void OnExit()
		{
			parent.barrageDelayStopwatchID = ChaosStopwatch.Begin(parent.curTurretProp.barrageDelayTime);
			parent.eyeLight.color = parent.ogLightColor;
		}
	}

	public class TurretDeadState : State<Turret>
	{
		public TurretDeadState(string stateName, FSM parentFSM, Turret parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
		}

		public override void OnEnter()
		{
			parent.anim.Play("Dead");
			if (parent.isEnemy)
			{
				GameController.enemies.Remove(parent.gameObject);
			}
			else
			{
				GameController.allies.Add(parent.gameObject);
			}
			if (!parent.isEnemy && parent.durationBar != null)
			{
				parent.durationBar.EndCast();
				UnityEngine.Object.Destroy(parent.durationBar.gameObject);
			}
			if (parent.gameObject != null)
			{
				UnityEngine.Object.Destroy(parent.gameObject);
			}
		}
	}

