				currentWP.attackBox.SetAttackInfo(parent.skillCategory, parent.skillID);
				currentWP.attackBox.knockbackOverwriteVector = targetVector;
				currentWP.moveVector = targetVector;
				currentWP.Show();
			}
		}
	}

