	public class WindKnightAirShieldState : SkillState
	{
		private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(4f);

		private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.25f);

		private NumVarStatMod evadeMod;

		private bool evadeActive;

		private ParticleEffect currentEffect;

		public new WindKnight parent;

		public WindKnightAirShieldState(string newName, FSM newFSM, WindKnight newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			requireLineOfSight = false;
			evadeMod = new NumVarStatMod(skillID, 1f, 10, VarStatModType.Override);
		}

		public override bool IsReady()
		{
			return base.IsReady() && !evadeActive;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.anim.Play("ChargeAlt", -1, 0f);
			evadeActive = false;
		}

		public override void WindupUpdate()
		{
			base.WindupUpdate();
			parent.anim.Play("ChargeAlt", -1, 0f);
		}

		public override void OnExit()
		{
			base.OnExit();
			if (!WindupCheck)
			{
				BreakShield();
			}
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.anim.Play("ChargeAlt", -1, 0.5f);
			DeactivatePowerUpEffect();
			PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(5, parent.hurtBoxTransform.position, ParticleEffectOverrides.StartSpeed1p5);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 100;
			float scale = 0.5f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			CameraController.ShakeCamera(0.3f);
			SoundManager.PlayAudioWithDistance("WindArrowStart", parent.transform.position, null, 24f, -1f, 0.6f);
			string audioID = "TornadoEnd";
			Vector2? soundOrigin = parent.transform.position;
			scale = UnityEngine.Random.Range(0.75f, 0.85f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, scale);
			parent.StartCoroutine(EvadeOn());
		}

		private void OnEvade()
		{
			PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(6, parent.hurtBoxTransform.position);
			string audioID = "TornadoEnd";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = UnityEngine.Random.Range(0.75f, 0.85f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			if (parent.health != null)
			{
				Health health = parent.health;
				health.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Remove(health.evadeEventHandlers, new Health.EvadeEventHandler(OnEvade));
			}
			if (parent.shieldDashState.IsReady())
			{
				fsm.ChangeState("WindKnightShieldDash");
			}
			else
			{
				BreakShield();
			}
		}

		public void BreakShield()
		{
			evadeActive = false;
			if (parent.health != null)
			{
				parent.health.evadeStat.Modify(evadeMod, addMod: false);
			}
			if (currentEffect != null && currentEffect.gameObject != null)
			{
				currentEffect.Stop();
				UnityEngine.Object.Destroy(currentEffect.gameObject, 1.5f);
			}
			string audioID = "TornadoEnd";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = UnityEngine.Random.Range(0.75f, 0.85f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
			StartCooldown();
		}

		private IEnumerator EvadeOn()
		{
			if (parent.health == null)
			{
				yield break;
			}
			evadeActive = true;
			parent.health.evadeStat.Modify(evadeMod, addMod: true);
			Health health = parent.health;
			health.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Remove(health.evadeEventHandlers, new Health.EvadeEventHandler(OnEvade));
			Health health2 = parent.health;
			health2.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Combine(health2.evadeEventHandlers, new Health.EvadeEventHandler(OnEvade));
			currentEffect = Globals.ChaosInst<ParticleEffect>(Player.UseWindDefense.EffectPrefab, parent.hurtBoxTransform, parent.hurtBoxTransform.position);
			ParticleEffect particleEffect = currentEffect;
			int? particleCount = 30;
			ParticleSystemOverride evadeEffectOverride = Player.UseWindDefense.evadeEffectOverride;
			particleEffect.Emit(particleCount, null, evadeEffectOverride);
			currentEffect.followTransform = parent.hurtBoxTransform;
			ParticleEffect particleEffect2 = currentEffect;
			evadeEffectOverride = Player.UseWindDefense.evadeEffectOverride;
			particleEffect2.Play(null, null, evadeEffectOverride);
			durationStopwatch.IsRunning = true;
			while (durationStopwatch.IsRunning && evadeActive)
			{
				if (!audioStopwatch.IsRunning)
				{
					audioStopwatch.IsRunning = true;
					string audioID = "WindCircle";
					Vector2? soundOrigin = parent.transform.position;
					float overridePitch = UnityEngine.Random.Range(0.9f, 1.1f);
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.075f, overridePitch);
				}
				yield return null;
			}
			BreakShield();
		}
	}

