		private NumVarStatMod dashDurationMod;

		private float dashSpeed = 40f;

		private float dashDuration = 0.15f;

		private bool dashStarted;

		private bool dashCompleted;

		private bool lanceReleased;

		private ParticleEffect drillEffect;

		public WindLancerWindLanceState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			dashSpeedMod = new NumVarStatMod("dashOverride", dashSpeed, 10, VarStatModType.OverrideWithMods);
			dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.movement.dashVector = targetVector;
			parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
			parent.movement.dashDurationStat.AddMod(dashDurationMod);
			parent.movement.dashTimer = dashDuration;
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.25f);
			parent.attack.transform.localEulerAngles = ((!parent.isFacingRight) ? (-Globals.GetRotationVector(targetVector)) : Globals.GetRotationVector(targetVector));
			CreateWindLance();
			parent.ToggleFloorContact(allyCollisionOn: false);
			dashStarted = false;
			dashCompleted = false;
			lanceReleased = false;
			drillEffect = PoolManager.GetPoolItem<ParticleEffect>("WindDrillEffect");
			drillEffect.Play(position: parent.attack.transform.position, localEulerAngles: Globals.GetRotationVector(targetVector), emissionRate: null, overrides: null, playTime: null, followTransform: parent.attack.transform);
			drillEffect.followOffset = targetVector * 1.5f;
			SoundManager.PlayAudioWithDistance("WindWindup", parent.transform.position);
		}

		public override void WindupUpdate()
		{
			parent.anim.PlayDirectional("AttackWindup");
		}

		public override void FixedUpdate()
		{
			if (dashStarted && !dashCompleted && parent.movement.DashToTarget())
			{
				dashCompleted = true;
				parent.ToggleFloorContact();
				parent.movement.moveVector = targetVector;
				parent.movement.MoveToMoveVector(10f);
				lanceReleased = true;
				if (currentWL != null)
				{
					currentWL.moveVector = targetVector;
					currentWL.moveSpeed = dashSpeed;
					currentWL.flyTime = dashDuration;
					currentWL.RefreshFlightTime();
				}
			}
			if (!lanceReleased && currentWL != null)
			{
				currentWL.transform.position = parent.attack.transform.position;
			}
		}

		public override void ExecuteSkill()
		{
			if (!dashStarted)
			{
				dashStarted = true;
				PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attack.transform.position, targetVector);
				PoolManager.GetPoolItem<SectionedTrailEmitter>("WindTrail").Emit(parent.hurtBoxTransform.position, parent.hurtBoxTransform.position + (Vector3)targetVector * 5f);
				parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 1f);
