		private Vector2 rightVec;

		private Projectile currentWF;

		private ParticleEffect flurryEffect;

		public override void OnEnter()
		{
			base.OnEnter();
			parent.attack.transform.localEulerAngles = ((!parent.isFacingRight) ? (-Globals.GetRotationVector(targetVector)) : Globals.GetRotationVector(targetVector));
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.125f);
			perpendVec = Globals.GetPerpendicular(targetVector) * 0.125f;
			leftVec = targetVector + perpendVec;
			rightVec = targetVector - perpendVec;
			attackStarted = false;
			flurryEffect = PoolManager.GetPoolItem<ParticleEffect>("WindCuttingBallEffect");
			flurryEffect.Play(position: parent.attack.transform.position, localEulerAngles: Globals.GetRotationVector(targetVector), emissionRate: null, overrides: null, playTime: null, followTransform: parent.attack.transform);
			flurryEffect.followOffset = targetVector * 1.25f;
			SoundManager.PlayAudioWithDistance("WindWindup", parent.transform.position);
		}

		public override void WindupUpdate()
		{
			base.WindupUpdate();
			parent.anim.PlayDirectional("AttackWindup");
		}

		public override void ExecuteSkill()
		{
			if (!attackStarted)
			{
				attackStarted = true;
				attackStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, attackInterval, attackCount);
				parent.anim.PlayDirectional("Attack" + parent.facingDirection, -1, 1f);
				DeactivatePowerUpEffect();
				if (flurryEffect != null)
				{
					flurryEffect.followOffset = targetVector * 1.75f;
				}
			}
			switch (ChaosStopwatch.CheckInterval(attackStopwatchID))
			{
			case StopwatchState.Ready:
				CreateWindFlurry(Vector2.Lerp(leftVec, rightVec, Random.value).normalized);
				break;
			case StopwatchState.Done:
				if (flurryEffect != null)
				{
					flurryEffect.Stop();
					flurryEffect = null;
				}
				base.ExecuteSkill();
				break;
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			if (flurryEffect != null)
			{
				flurryEffect.Stop();
				flurryEffect.effectEmitter.Clear();
				flurryEffect = null;
			}
		}

		private void CreateWindFlurry(Vector2 givenVector)
		{
			currentWF = ChaosInst<Arrow>(Arrow.Prefab, (Vector2)parent.attack.transform.position + givenVector * 0.8f + Random.insideUnitCircle * 0.5f, Globals.GetRotationQuaternion(givenVector));
			currentWF.parentObject = parent.gameObject;
			currentWF.parentEntity = parent;
			currentWF.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentWF.moveVector = givenVector;
			SoundManager.PlayWithDistAndSPR("WindSnap", currentWF.transform.position);
			SoundManager.PlayWithDistAndSPR("WindCircle", currentWF.transform.position);
		}
	}

