	public class WindMageSpreadShotState : BaseSpreadShotState
	{
		private Vector3 shootVector;

		private Vector3 effectPos;

		private ParticleEffect miniTornadoEffect;

		private ParticleEffect spinBurstEffect;

		private DustSuctionEffect dustSuctionEffect;

		private new float castTime;

		private float effectTime;

		public WindMageSpreadShotState(string newName, FSM newFSM, Enemy newEnt)
			: base(newName, newFSM, newEnt)
		{
			projectilePrefab = MultiShotArrow.Prefab;
			castingAnimName = "PBAoE";
			projectileCount = 5;
			holdTime = 0f;
			totalPositionCount = 30;
			spawnRange = 0.125f;
		}

		public override void OnExit()
		{
			base.OnExit();
			if (miniTornadoEffect != null)
			{
				miniTornadoEffect.Stop();
			}
			if (spinBurstEffect != null)
			{
				spinBurstEffect.Stop();
			}
			if (dustSuctionEffect != null)
			{
				dustSuctionEffect.Stop();
			}
		}

		public override void FireAllProjectiles()
		{
			base.FireAllProjectiles();
			parent.movement.moveVector = -targetVector;
			parent.movement.MoveToMoveVector(7f);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 60;
			float scale = 0.25f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			miniTornadoEffect.Stop();
			spinBurstEffect.Stop();
			dustSuctionEffect.Stop();
			SoundManager.PlayWithDistAndSPR("WindArrowEnd", parent.transform.position);
		}

		public override void InitalizeAttack()
		{
			base.InitalizeAttack();
			castTime = StdWindupTime * 1.75f;
			effectTime = castTime * 0.8f;
			castStopwatchID = ChaosStopwatch.Begin(castTime);
			shootVector = Globals.GetRotationVector(targetVector);
			effectPos = parent.hurtBoxTransform.position + (Vector3)targetVector * 0.5f;
			miniTornadoEffect = PoolManager.GetPoolItem<ParticleEffect>("MiniTornadoEffect");
			miniTornadoEffect.Play(14f, effectPos, localEulerAngles: shootVector, overrides: null, playTime: effectTime);
			spinBurstEffect = PoolManager.GetPoolItem<ParticleEffect>("SpinningCircleBurst");
			spinBurstEffect.Play(4f, effectPos, localEulerAngles: shootVector, overrides: null, playTime: effectTime);
			dustSuctionEffect = PoolManager.GetPoolItem<DustSuctionEffect>();
			dustSuctionEffect.Play(60f, effectPos, localEulerAngles: shootVector, overrides: null, playTime: effectTime);
		}

		public override bool CreateAllProjectiles()
		{
			if (!ChaosStopwatch.Check(castStopwatchID))
			{
				return false;
			}
			for (int i = 0; i < projectileCount; i++)
			{
				projectileList.Add(CreateProjectile(Globals.GetRotatedCircleVector(totalPositionCount, positionCount % totalPositionCount, targetVector)));
				positionCount++;
			}
			return true;
		}

		public override void ExtraCreateSettings(Projectile givenProj)
		{
			givenProj.flyTime = 0.275f;
			givenProj.moveSpeed = 5f;
			givenProj.RefreshFlightTime();
		}
	}

