			wbEffect = PoolManager.GetPoolItem<ParticleEffect>("WindBallSmallEffect");
			wbEffect.followTransform = parent.hurtBoxTransform;
			wbEffect.followOffset = effectOffset;
			wbEffect.reqFollowTrans = true;
			wbEffect.Play(0.5f, parent.hurtBoxTransform.position + effectOffset, ParticleEffectOverrides.LayerOverlayDoodad);
