		public WindRogueBlastDashState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
		{
			useTargetHurtBox = false;
			dashAway = true;
			dashSpeed = 24f;
			dashRange = 3.5f;
			randomOffSet = 0.75f;
			evadeMod = new NumVarStatMod(skillID, 1f, 10, VarStatModType.Override);
			usePowerUpEffect = false;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("BackDash", -1, 0f);
			parent.movement.EndMovement();
			parent.health.evadeStat.AddMod(evadeMod);
		}

		public override void ExitTransition()
		{
			if (!exitQueued)
			{
				exitQueued = true;
				parent.health.evadeStat.RemoveMod(evadeMod);
				windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 0.875f);
				ActivatePowerUpEffect(spellCastColor);
				parent.FaceTarget(parent.transform.position + (Vector3)targetVector);
			}
			if (!windupComplete)
			{
				if (ChaosStopwatch.Check(windupStopwatchID))
				{
					windupComplete = true;
					CreateAirChannel(parent.hurtBoxTransform.position, targetVector);
					parent.anim.PlayDirectional("Stab" + parent.facingDirection, -1, 1f);
					DeactivatePowerUpEffect();
					exitStopwatchID = ChaosStopwatch.Begin(StdExitTime);
					CameraController.ShakeCamera(0.2f);
				}
				else
				{
					parent.anim.PlayDirectional("Stab" + parent.facingDirection);
				}
			}
			else if (ChaosStopwatch.Check(exitStopwatchID))
			{
				base.ExitTransition();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.health.evadeStat.RemoveMod(evadeMod);
		}

		private void CreateAirChannel(Vector2 givenPosition, Vector2 givenVector)
		{
			currentAC = ChaosInst<AirChannel>(AirChannel.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
			currentAC.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentAC.attack.knockbackOverwriteVector = givenVector;
			currentAC.targetVector = givenVector;
			currentAC.useShockwaveEffect = true;
		}
	}

	public class WindRogueWindShurikenState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD) : SkillState(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
	{
		private WindShuriken currentFS;

		private int shotStopwatchID;

		private int shotCount = 2;

		private float shotInterval = 0.15f;

		private bool shotStarted;

		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime);
			shotStarted = false;
		}

		public override void WindupUpdate()
		{
			parent.anim.Play("Backhand", -1, 0f);
		}

		public override void ExecuteSkill()
		{
			if (!shotStarted)
			{
				shotStarted = true;
				shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotInterval, shotCount);
				DeactivatePowerUpEffect();
				parent.anim.Play("Backhand", -1, 1f);
				SoundManager.PlayAudioWithDistance("RogueAttack", parent.transform.position);
				PoolManager.GetPoolItem<ParticleEffect>("WindBurstEffect").Emit(3, parent.hurtBoxTransform.position + (Vector3)targetVector);
			}
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				CreateWindShuriken();
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				break;
			}
		}

		private void CreateWindShuriken()
		{
			currentFS = ChaosInst<WindShuriken>(WindShuriken.Prefab, parent.hurtBoxTransform.position);
			currentFS.parentObject = parent.gameObject;
			currentFS.parentEntity = parent;
			currentFS.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentFS.moveVector = targetVector;
			if (parent.closestTargetInfo != null)
			{
				currentFS.targetTrans = parent.closestTargetInfo.hurtBoxTransform;
			}
		}
	}

	public class WindRogueSlicingBarrageState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD) : SkillState(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD)
	{
		private static float[] angleOffsets = new float[3] { -30f, 0f, 30f };

		private int sliceStopwatchID;

		private int sliceCount = 5;

		private float sliceInterval = 0.1f;

		private bool sliceStarted;

		private SlicingBarrage currentSB;

		private Vector3 sliceVec;

		private int sliceCounter;

		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.PlayDirectional("Charging");
			parent.movement.moveVector = targetVector;
			windupStopwatchID = ChaosStopwatch.Begin(StdWindupTime * 1.125f);
			exitTime = StdExitTime * 1.5f;
			sliceStarted = false;
			sliceCounter = 0;
		}

		public override void ExecuteSkill()
		{
			if (!sliceStarted)
			{
				sliceStarted = true;
				sliceStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, sliceInterval, sliceCount);
			}
			switch (ChaosStopwatch.CheckInterval(sliceStopwatchID))
			{
			case StopwatchState.Ready:
				sliceCounter++;
				parent.movement.MoveToMoveVector(12f);
				if (sliceCounter % 2 == 0)
				{
					parent.anim.PlayDirectional("Backhand");
				}
				else
				{
					parent.anim.PlayDirectional("Attack", -1, 1f);
				}
				CreateSlice(ChaosStopwatch.CheckInterval(sliceStopwatchID, getCharge: false) == StopwatchState.Done);
				break;
			case StopwatchState.Done:
				parent.anim.PlayDirectional("Attack", -1, 1f);
				DeactivatePowerUpEffect();
				base.ExecuteSkill();
				break;
			}
		}

		private void CreateSlice(bool isFinal)
		{
			if (isFinal)
			{
				WindSlashProjectile windSlashProjectile = ChaosInst<WindSlashProjectile>(WindSlashProjectile.Prefab, parent.hurtBoxTransform.position, Globals.GetRotationQuaternion(targetVector));
				windSlashProjectile.moveVector = targetVector;
				windSlashProjectile.attackBox.SetAttackInfo(parent.skillCategory, skillID, 2);
				windSlashProjectile.attackBox.knockbackOverwriteVector = targetVector;
				string audioID = "WindArrowEnd";
				Vector2? soundOrigin = parent.transform.position;
				float overridePitch = Random.Range(0.75f, 0.85f);
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
				windSlashProjectile.playBlastAudio = false;
				windSlashProjectile.alwaysWinCollision = true;
			}
			else
			{
				currentSB = ChaosInst<SlicingBarrage>(SlicingBarrage.Prefab, parent.hurtBoxTransform.position + (Vector3)targetVector * 0.25f, Globals.GetRotationQuaternion(targetVector));
				currentSB.attack.SetAttackInfo(parent.skillCategory, skillID);
				currentSB.attack.knockbackOverwriteVector = targetVector;
				sliceVec = currentSB.transform.localEulerAngles;
				sliceVec.z += angleOffsets[sliceCounter % 3];
				currentSB.transform.localEulerAngles = sliceVec;
				currentSB.anim.Play("MedSlashAdvancing", -1, 0f);
			}
		}
	}

