		private void ShootArrows()
		{
			targetVector = Globals.GetCirclePositionVector(maxIndex, currentIndex);
			CreateArrow(targetVector);
			CreateArrow(-targetVector);
			parent.attackEffectTrans.localEulerAngles = ((!(parent.transform.localScale.x < 1f)) ? Globals.GetRotationVector(targetVector) : (-Globals.GetRotationVector(targetVector)));
			SoundManager.PlayAudioWithDistance("WindArrowStart", parent.transform.position, null, 24f, -1f, 1.1f);
		}

		public override void ExecuteAttack()
		{
			if (!warningShotStarted)
			{
				warningShotTimerID = ChaosStopwatch.Begin(0f, useInterval: true, shotInterval, warningShotCount);
				warningShotStarted = true;
				if (parent.windPartSys != null)
				{
					parent.windPartSys.Stop();
				}
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 80;
				float scale = 0.75f;
				float startSpeed = 0.25f;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
			}
			if (!warningShotsDone)
			{
				switch (ChaosStopwatch.CheckInterval(warningShotTimerID))
				{
				case StopwatchState.Ready:
					ShootArrows();
					break;
				case StopwatchState.Done:
					warningShotsDone = true;
					shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotInterval, shotCount);
					break;
				}
				return;
			}
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				ShootArrows();
				currentIndex++;
				break;
			case StopwatchState.Done:
				parent.anim.Play("Idle", -1, 0f);
				if (parent.attackEffect0 != null)
				{
					parent.attackEffect0.Stop();
				}
				if (parent.attackEffect1 != null)
				{
					parent.attackEffect1.Stop();
				}
				base.ExecuteAttack();
				break;
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			if (parent.windPartSys != null)
			{
				parent.windPartSys.Stop();
			}
			if (parent.attackEffect0 != null)
			{
				parent.attackEffect0.Stop();
			}
			if (parent.attackEffect1 != null)
			{
				parent.attackEffect1.Stop();
			}
		}

		private void CreateArrow(Vector2 givenVector)
		{
			currentAC = Globals.ChaosInst<Arrow>(Arrow.Prefab, null, (Vector2)parent.atkTrans.position + givenVector * 0.5f, Globals.GetRotationQuaternion(givenVector));
			currentAC.parentObject = parent.gameObject;
			currentAC.parentEntity = parent;
			currentAC.attackBox.SetAttackInfo(parent.skillCategory, "WindZoneAttack");
			currentAC.attackBox.knockbackOverwriteVector = givenVector;
			currentAC.moveVector = givenVector;
			currentAC.flyTime = 0.25f;
			currentAC.moveSpeed = 20f;
		}
